    /* ---- Auto Tune Styles ---- */
    'tuneStyles.natural.name': 'Natural Pop',
    'tuneStyles.natural.tip': 'Articulated repeated-note scoops, dip-and-lift entries, crest overshoots with rebound, and gradual vibrato on sustained notes.',
    'tuneStyles.ballad.name': 'Gentle Ballad',
    'tuneStyles.ballad.tip': 'Slow legato transitions with anticipation, deep phrase-initial scoops, wide slow vibrato fading in gently, and soft phrase-end falls.',
    'tuneStyles.bright.name': 'Bright & Upbeat',
    'tuneStyles.bright.tip': 'Snappy interval leaps with crisp overshoot and rebound, frequent pitch scoops, fast shallow vibrato, and upward phrase-end flicks.',
    'tuneStyles.rock.name': 'Power Rock',
    'tuneStyles.rock.tip': 'Deep scoops, strong dip-and-lift inflections, bold crest overshoots, wide energetic vibrato, and dramatic phrase-end fall-offs.',
    'tuneStyles.electronic.name': 'Flat Electronic',
    'tuneStyles.electronic.tip': 'Instant linear pitch snapping with zero vibrato or overshoot for a hard-tuned robotic feel and even dynamics.',
    'tuneStyles.enka.name': 'Enka',
    'tuneStyles.enka.tip': 'Rich kobushi ornamentation with repeated scoops, deep phrase-initial inflections, wide slow swaying vibrato, and deep phrase-end falls.',
    'tuneStyles.da.name': 'All',
    'tuneStyles.da.tip': 'Warm, natural pitch transitions with expressive crest overshoots and mid-phrase turns, ~4.7 Hz full-bodied singing vibrato with smooth fade-in, and gentle phrase-end falls.',

    /* ---- Auto Arrange Styles & Moods ---- */
    'arrangeStyles.pop.name': 'Pop',
    'arrangeStyles.pop.tip': 'Tine EP to reed EP layering, music box/vibraphone and synth choir buildup, with strings and brass fills in the chorus.',
    'arrangeStyles.ballad.name': 'Ballad',
    'arrangeStyles.ballad.tip': 'Interlocking fingerpicking and sustained bass over warm pad harmonies, EP and vibraphone highlights, opening to piano and strings in the chorus.',
    'arrangeStyles.rock.name': 'Rock',
    'arrangeStyles.rock.tip': 'Palm-muted electric guitar building to overdrive and distortion power chords, eighth-note picked bass, and inter-phrase guitar fills.',
    'arrangeStyles.edm.name': 'EDM',
    'arrangeStyles.edm.tip': 'Dotted/octave-jumping synth bass with syncopated 7th/9th plucks, 16th-note waveform arps, off-beat open hats, and synth fifth sweeps.',
    'arrangeStyles.folk.name': 'Folk',
    'arrangeStyles.folk.tip': 'Acoustic guitar strumming with marimba/harp plucks, flute fills, pizzicato strings, and 16th-note shaker groove.',
    'arrangeStyles.piano.name': 'Piano Ballad',
    'arrangeStyles.piano.tip': 'Left-hand arpeggios and right-hand chords, harp and music box upper accents, supported by choir and strings in the chorus.',
    'arrangeStyles.citypop.name': 'City Pop',
    'arrangeStyles.citypop.tip': 'Syncopated reed EP seventh chords with chorus slap bass, brass stabs, and clean guitar fills.',
    'arrangeStyles.guofeng.name': 'Chinese Trad.',
    'arrangeStyles.guofeng.tip': 'Harp/guzheng plucks and pizzicato strings trading phrases with flute, anchored by vocal choir and taiko-style low drums.',
    'arrangeStyles.bossa.name': 'Bossa Nova',
    'arrangeStyles.bossa.tip': 'Two-bar syncopated nylon guitar, root-fifth fingerstyle bass, marimba and vibraphone accents, and sparse flute fills.',
    'arrangeStyles.polka.name': 'Polka',
    'arrangeStyles.polka.tip': 'Classic oom-pah feel: tuba on downbeats, accordion on off-beats, with clarinet and brass phrase-end answers.',
    'arrangeStyles.synthpop.name': 'Synthpop',
    'arrangeStyles.synthpop.tip': 'Octave and acid synth bass, evolving PWM to retro synth brass, tight arps, and synth fifth leads.',
    'arrangeStyles.dreampop.name': 'Dreampop',
    'arrangeStyles.dreampop.tip': 'Layered clean electric guitar arpeggios, music box and vibraphone sparkles, hollow-to-shimmer pads, and half-time drums with floor toms.',
    'arrangeStyles.chiptune.name': 'Chiptune',
    'arrangeStyles.chiptune.tip': 'Automatically enables 8-bit timbres: octave-jumping triangle bass, fast chord arpeggios, and square-wave runs.',
    'arrangeStyles.enka.name': 'Enka',
    'arrangeStyles.enka.tip': 'Slow 8-beat groove with root-fifth bass, fingerpicked verse guitar, off-beat clean chorus chops, expressive strings, harmonic minor V7, and guitar/accordion fills.',
    'arrangeStyles.da.name': 'All',
    'arrangeStyles.da.tip': 'Eighth-note guitar pulse with crisp piano chords, music box/harp/vibraphone upper accents, clarinet fills, and choir strings.',

