    'eyePresets.单眼·峰偏左.name': 'Single · Left Peak',
    'eyePresets.单眼·峰偏左.tip': 'Most natural and common: one breath climbing to a peak around 85% before settling.',
    'eyePresets.三眼·上下上.name': 'Triple · Up-Down-Up',
    'eyePresets.三眼·上下上.tip': 'Three waves in a phrase, closest to natural speech cadence for pop.',
    'eyePresets.大拱·抒情.name': 'Grand Arch · Lyrical',
    'eyePresets.大拱·抒情.tip': 'Gradually climbs an octave and descends slowly for lyrical phrases.',
    'eyePresets.双眼·问答.name': 'Dual · Q&A',
    'eyePresets.双眼·问答.tip': 'Two arches, low then high, like question and answer lines.',
    'eyePresets.上扬·收尾高.name': 'Ascending · High End',
    'eyePresets.上扬·收尾高.tip': 'Rises continuously and peaks at the end—great for choruses.',
    'eyePresets.下行·叹息.name': 'Descending · Sigh',
    'eyePresets.下行·叹息.tip': 'Starts high and falls steadily—suited for sad or closing lines.',
    'eyePresets.锯齿·说唱.name': 'Sawtooth · Rap',
    'eyePresets.锯齿·说唱.tip': 'Four small sharp peaks staying close to spoken pitch.',
    'eyePresets.童谣·跳动.name': 'Nursery · Bounce',
    'eyePresets.童谣·跳动.tip': 'Two short crisp jumps landing back on the tonic.',

