    'about.title': 'NSG 노래소리 합성기 소개',
    'about.heading': 'NSG 노래소리 합성기 V10',
    'about.p1': '합성기관: 최대 64차 배음(명시 16차 + −12 dB/oct 감쇠, 고정 무작위 위상)으로 려파 전 성대원음을 생성하고, 6단 직렬 구강 공진봉 려파기(F1–F6, 이 중 F4/F5/F6은 음색묶음에서 지정)와 극영점 비강분기를 병렬로 통과시킵니다. 무성마찰음은 별도 병렬 잡음경로로 처리한 뒤 입술방사(+6 dB/oct)를 거쳐 출력합니다.',
